// native_flora_register.cpp — registers every native of native_flora_decl.h with
// bronze (embed::registerNative) under __bro_native.flora. Generated by brosurface
// (gen/emit_natives.mjs); do not edit. Call registerNatives_flora from registerBroNatives
// (src/bronze_host/host_natives.h) on the thread that runs the program.
//
// Class members are Function-kind natives taking the handle first (the wrapper's
// receiver is dynamic, so a Method-kind registration would be unreachable from it);
// each class has one Constructor-kind registration, which mints the class, and its
// prototype is published as __bro_native.flora.<Class>Proto for flora.js to chain.

#include "native_flora_decl.h"

#include "embed/embed.h"

#include <initializer_list>
#include <string>

namespace bro::bronze_host {

namespace {

namespace ev = bronze::embed;

ev::NativeSignature sig(const char* ret, std::initializer_list<const char*> params, ev::NativeKind kind) {
    ev::NativeSignature s;
    s.returnType = ret;
    for (const char* p : params) s.paramTypes.emplace_back(p);
    s.kind = kind;
    return s;
}

bool fn(const char* path, void* f, const char* ret, std::initializer_list<const char*> params, std::string* error) {
    return ev::registerNative(path, f, sig(ret, params, ev::NativeKind::Function), error);
}

bool ctor(const char* path, void* f, ev::HandleDestructor dtor, bronze::runtime::Finalize finalize,
          std::initializer_list<const char*> params, std::string* error) {
    ev::NativeSignature s = sig(path, params, ev::NativeKind::Constructor);
    s.className = path;
    s.destructor = dtor;
    s.finalize = finalize;
    return ev::registerNative(path, f, s, error);
}

// The prototype every instance of a class is born on, published where the
// wrapper reads it. Skipped when the roots are not there (bro-native-manifest
// registers without them; the manifest does not need the prototype).
void publishPrototype(const char* ns, const char* className, const char* protoName) {
    ev::GlobalValue root = ev::globalValue("__bro_native");
    if (!root.found || !ev::isObject(root.value)) return;
    ev::GlobalValue proto = ev::nativeClassPrototype(className);
    if (!proto.found) return;
    // Each value rooted before the next allocating call (bronze embed GC contract).
    ev::Persistent rootSlot(root.value);
    ev::Persistent protoSlot(proto.value);
    ev::Persistent nsSlot(ev::getProperty(rootSlot.get(), ns));
    if (!ev::isObject(nsSlot.get())) return;
    ev::setProperty(nsSlot.get(), protoName, protoSlot.get());
}

template <typename F>
void* p(F* f) { return reinterpret_cast<void*>(f); }

}  // namespace

bool registerNatives_flora(std::string* error) {
    bool ok =
        ctor("__bro_native.flora.FloraWorld", p(&bro_flora_FloraWorld_ctor), &bro_flora_FloraWorld_dtor, bronze::runtime::Finalize::InSweep, {}, error) &&
        fn("__bro_native.flora.FloraWorld_addVoronoiSite", p(&bro_flora_FloraWorld_addVoronoiSite), "__bro_native.flora.FloraWorld", {"__bro_native.flora.FloraWorld", "i32", "f64", "f64"}, error) &&
        fn("__bro_native.flora.FloraWorld_removePlant", p(&bro_flora_FloraWorld_removePlant), "bool", {"__bro_native.flora.FloraWorld", "i32"}, error) &&
        fn("__bro_native.flora.FloraWorld_step", p(&bro_flora_FloraWorld_step), "__bro_native.flora.FloraWorld", {"__bro_native.flora.FloraWorld", "f64"}, error) &&
        fn("__bro_native.flora.FloraWorld_simTime_get", p(&bro_flora_FloraWorld_simTime_get), "f64", {"__bro_native.flora.FloraWorld"}, error) &&
        fn("__bro_native.flora.FloraWorld_plantCount_get", p(&bro_flora_FloraWorld_plantCount_get), "i32", {"__bro_native.flora.FloraWorld"}, error) &&
        fn("__bro_native.flora.FloraWorld_prototypeCount_get", p(&bro_flora_FloraWorld_prototypeCount_get), "i32", {"__bro_native.flora.FloraWorld"}, error) &&
        fn("__bro_native.flora.FloraWorld_moduleCount_get", p(&bro_flora_FloraWorld_moduleCount_get), "i32", {"__bro_native.flora.FloraWorld"}, error);
#if BRO_WITH_FLORA
    ok = ok &&
        fn("__bro_native.flora.setWind", p(&bro_flora_setWind), "void", {"f64", "f64", "f64"}, error) &&
        fn("__bro_native.flora.wind", p(&bro_flora_wind), "void", {"f64", "f64", "f64"}, error) &&
        fn("__bro_native.flora.setDensity", p(&bro_flora_setDensity), "void", {"f64"}, error) &&
        fn("__bro_native.flora.density", p(&bro_flora_density), "void", {"f64"}, error) &&
        fn("__bro_native.flora.update", p(&bro_flora_update), "void", {"f64"}, error) &&
        fn("__bro_native.flora.clear", p(&bro_flora_clear), "void", {}, error);
#endif
    if (!ok) return false;
    publishPrototype("flora", "__bro_native.flora.FloraWorld", "FloraWorldProto");
    return true;
}

}  // namespace bro::bronze_host
